import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const api = readFileSync(new URL('../api.php', import.meta.url), 'utf8');
const html = readFileSync(new URL('../index.php', import.meta.url), 'utf8');
const script = readFileSync(new URL('../script.js', import.meta.url), 'utf8');
assert.match(api, /HITMOS_SEARCH_API_URL/);
assert.match(api, /\$urls\['hitmos'\]/);
assert.match(api, /\$source_status\['hitmos'\]/);
assert.match(api, /'configured' => false/);
assert.match(api, /\$hitmos_data\['tracks'\]/);
assert.match(api, /\$track\['audio_url'\]/);
assert.match(api, /'source' => '\[HITMOS\]'/);
assert.match(api, /'hitmos' => '\[HITMOS\]'/);
assert.match(api, /CURLOPT_FOLLOWLOCATION,\s*!in_array\(\$key,\['jamendo','hitmos','partner'\],true\)\)/);
const config=readFileSync(new URL('../hitmos-config.php',import.meta.url),'utf8');
const proxy=readFileSync(new URL('../proxy.php',import.meta.url),'utf8');
assert.match(config,/HITMOS_AUDIO_HOSTS/);
assert.match(config,/function dagHitmosAudioHosts/);
assert.match(api,/require_once __DIR__ \. '\/hitmos-config\.php'/);
assert.match(api,/count\(\$hitmos_audio_hosts\) > 0/);
assert.match(api,/in_array\(\$audio_host, \$hitmos_audio_hosts, true\)/);
assert.match(proxy,/dagHitmosAudioHosts\(\)/);
assert.match(proxy,/CURLOPT_FOLLOWLOCATION => \$source !== 'hitmos'/);
assert.match(script,/key:'hitmos',label:'Hitmos\.fm',source:'\[HITMOS\]'/);
assert.match(script,/Hitmos\/Jamendo по API/);
assert.doesNotMatch(html, /hitmos-external-link/);
assert.doesNotMatch(script, /renderHitmosExternalResult|hitmos-search-result/);
console.log('HITMOS_JSON_ONLY_OPTIONAL_PROVIDER_NO_FAKE_RESULTS_OK');
